INSERT INTO catalogo.colonia (nombre, tipo, codigo_postal, latitud, longitud, localidad_id) SELECT 'LA CARDONA', 'otro', NULL, NULL, NULL, (SELECT id FROM catalogo.localidad  WHERE municipio_id = m.id  ORDER BY poblacion_total DESC NULLS LAST LIMIT 1) FROM catalogo.municipio m WHERE m.clave_inegi = '004' AND NOT EXISTS (  SELECT 1 FROM catalogo.colonia c2   WHERE LOWER(c2.nombre) = LOWER('LA CARDONA')     AND c2.localidad_id = (SELECT id FROM catalogo.localidad WHERE municipio_id = m.id ORDER BY poblacion_total DESC NULLS LAST LIMIT 1));
